// Castle Tower — grand medieval stone tower with voronoi stone texture
// Z-up, tower centered at X=0 Y=0, base at Z=0, door on the -Y face
// Total height: ~43 (base 2 + tower 27 + parapet 3 + merlons 3 + roof 11)
//
// Mesh note: the in-app voronoi texture is scoped to the 'stone' label and the
// label colours are carried onto the textured mesh using THIS mesh's triangle
// centroids. So every round body is built with extrude(h, nDivisions) (~1 unit
// quads) instead of one long sliver per facet, and the small boxes are refined —
// uniform fine triangles keep the texture and the colours clean at the door.

const { Manifold, CrossSection } = api;

// === DIMENSIONS ===
const towerR       = 9.0;    // main tower radius
const baseR        = 11.0;   // battered base ring radius
const baseH        = 2.0;    // base ring height
const towerH       = 27.0;   // tower body height (above base)
const parapetR     = 9.8;    // parapet ring slightly wider
const parapetH     = 2.5;    // parapet ring height (slightly taller)
const parapetZ     = baseH + towerH;
const merlonH      = 3.2;    // merlon height above parapet top (taller for prominence)
const roofBaseR    = 8.8;    // cone base fits INSIDE the parapet ring
const roofZ        = parapetZ + parapetH - 0.2;
const roofH        = 11.5;   // cone height

// A round frustum with ~1-unit quad rows (r0 at z0, r1 at z0 + h).
function frustum(r0, r1, h, z0, seg = 64) {
  return CrossSection.circle(r0, seg)
    .extrude(h, Math.max(1, Math.round(h)), 0, [r1 / r0, r1 / r0])
    .translate([0, 0, z0]);
}

// === BASE (battered, wider at bottom) ===
// The lowest course ("plinth") is its own label so the stone texture never
// touches the bottom face: the tower rests flat on z=0 after texturing.
const plinthH = 1.2;
const baseTopR = towerR + 0.3;                        // base cone: baseR at z=0 -> baseTopR at z=baseH
const plinthTopR = baseR + (baseTopR - baseR) * (plinthH / baseH);
const plinth   = frustum(baseR, plinthTopR, plinthH, 0);
const baseUp   = frustum(plinthTopR, baseTopR, baseH - plinthH, plinthH);

// === TOWER BODY (slight taper) ===
const towerBody = frustum(towerR, towerR - 0.5, towerH + 0.5, baseH - 0.5);

// === PARAPET RING ===
const parapetRing = frustum(parapetR, parapetR, parapetH, parapetZ);

// === CRENELLATIONS — 8 merlons ===
const numMerlons    = 8;
const sectorAng     = 360 / numMerlons;   // 45°
const merlonArcFrac = 0.50;               // merlon uses 50% of arc
const merlonZ       = parapetZ + parapetH;

const arcLen        = 2 * Math.PI * parapetR * (merlonArcFrac / numMerlons);
const merlonWidth   = arcLen;             // tangential size
const merlonDepth   = 2.8;               // radial size
const merlonCenterR = parapetR - merlonDepth / 2 + 0.4;  // radial placement

let merlons = [];
for (let i = 0; i < numMerlons; i++) {
  const angle = i * sectorAng;
  const merlon = Manifold.cube([merlonDepth + 0.6, merlonWidth, merlonH + 0.5])
    .refine(3)
    .translate([
      merlonCenterR - (merlonDepth + 0.6) / 2,
      -merlonWidth / 2,
      merlonZ - 0.5  // overlap 0.5 into parapet top for guaranteed union
    ])
    .rotate([0, 0, angle]);
  merlons.push(merlon);
}
const allMerlons = Manifold.union(merlons);

// === GOTHIC (POINTED) ARCH PROFILE ===
// Equilateral pointed arch: two circles of radius w, each centred on the
// opposite spring point; the lens above the spring line is the pointed head.
// Profile is in (x, up); total height h, base at 0.
function gothic(w, h) {
  const rise = w * Math.sin(Math.PI / 3);        // apex height above the spring line
  const zs   = h - rise;                         // spring-line height
  const rect = CrossSection.square([w, zs]).translate([-w / 2, 0]);
  const lens = CrossSection.circle(w, 48).translate([ w / 2, zs])
    .intersect(CrossSection.circle(w, 48).translate([-w / 2, zs]))
    .intersect(CrossSection.square([w * 2, rise + 1]).translate([-w, zs]));
  return CrossSection.union([rect, lens]);
}
// Extrude a profile toward -Y: occupies y in [yFront, yBack], bottom at z0.
function onFace(profile, yFront, yBack, z0, nDiv = 1) {
  return profile.extrude(yBack - yFront, nDiv)
    .rotate([90, 0, 0])
    .translate([0, yBack, z0]);
}

// === DOOR — recessed gothic doorway on the -Y face ===
const doorW  = 3.4;
const doorH  = 6.0;
const doorZ  = baseH + 0.5;
// Pocket cut into the wall (wall surface is at y = -towerR): 1.6 deep, open to the front.
const doorCutter = onFace(gothic(doorW, doorH), -(towerR + 2.5), -(towerR - 1.6), doorZ);

// Wooden door leaf, set 0.6 behind the wall face, fused into the pocket back.
// (A hair oversize so its edges overlap the pocket walls — no coplanar faces.)
const doorLeaf = onFace(gothic(doorW + 0.2, doorH + 0.1), -(towerR - 0.6), -(towerR - 1.7), doorZ - 0.05, 3)
  .refine(2);

// Stone door surround: a pointed-arch dressed-stone frame that lines the pocket and
// stands proud of the wall around the opening. It is its OWN label (untextured), so
// the voronoi texture stops a clear 1 unit away from the wooden door and the door
// edge stays clean. The opening is a hair smaller than the pocket so the two never
// share a coplanar wall.
const frameW = doorW + 2.0;
const frameH = doorH + 1.3;
const doorSurround = onFace(gothic(frameW, frameH), -(towerR + 1.0), -(towerR - 1.8), baseH + 0.3, 2)
  .subtract(onFace(gothic(doorW - 0.1, doorH - 0.05), -(towerR + 2.0), -(towerR - 2.5), doorZ + 0.02, 1))
  .refine(2);
const woodwork = doorLeaf.refine(4);

// === ARROW SLIT WINDOWS — 3 narrow vertical slots ===
const slitW = 0.9;
const slitH = 4.2;
const slitD = 5.5;  // more than 2×wall thickness to ensure clean cut

function makeSlitCutter(zCenter, angle) {
  return Manifold.cube([slitW, slitD, slitH])
    .translate([-slitW / 2, -towerR - 2.0, zCenter - slitH / 2])
    .rotate([0, 0, angle]);
}

// 3 windows at distinct angles (away from door at 0°)
const slit1 = makeSlitCutter(baseH + 9.0,   72);
const slit2 = makeSlitCutter(baseH + 17.5, -72);
const slit3 = makeSlitCutter(baseH + 24.0,  135);
const allSlits = Manifold.union([slit1, slit2, slit3]);

// Arrow slit frames: thin raised border around each slit, starting 1.0 inside
// the tower surface so it is always fused.
function makeSlitFrame(zCenter, angle) {
  const fw = slitW + 1.6;
  const fh = slitH + 1.6;
  const fd = 1.4;           // only 0.4 protrusion beyond the surface (1.4 - 1.0 inside)
  const frameInner = towerR - 1.0;
  return Manifold.cube([fw, fd, fh])
    .refine(3)
    .translate([-fw / 2, -(frameInner + fd), zCenter - fh / 2])
    .rotate([0, 0, angle]);
}

const frame1 = makeSlitFrame(baseH + 9.0,   72);
const frame2 = makeSlitFrame(baseH + 17.5, -72);
const frame3 = makeSlitFrame(baseH + 24.0,  135);
const allSlitFrames = Manifold.union([frame1, frame2, frame3]);

// === STONE BODY === (frames unioned in FIRST, then door pocket + slits cut)
const stoneSolid = Manifold.union([baseUp, towerBody, parapetRing, allMerlons, allSlitFrames]);
const stoneWithOpenings = stoneSolid
  .subtract(doorCutter)
  .subtract(allSlits);

// === CONICAL ROOF === (merlons rise above the roof base)
const roofCone = frustum(roofBaseR, 0.15, roofH, roofZ);

// === LABEL PARTS ===
const plinthLabeled = api.label(plinth,            'plinth',   { color: '#8a8a8a' });
const stoneLabeled  = api.label(stoneWithOpenings.refine(2), 'stone',    { color: '#8a8a8a' });
const roofLabeled   = api.label(roofCone.refine(2), 'roof',     { color: '#1e3a7a' });
const woodLabeled   = api.label(woodwork, 'woodwork', { color: '#3d2610' });
const surroundLabeled = api.label(doorSurround, 'surround', { color: '#8a8a8a' });

// === ASSEMBLE ===
const assembled = Manifold.union([plinthLabeled, stoneLabeled, roofLabeled, woodLabeled, surroundLabeled]);

// === VORONOI STONE TEXTURE === (stone only: not the plinth/bottom face, door surround, door or roof)
api.surface.voronoi({
  amplitude: 0.52,
  cellSize: 7,
  wallWidth: 0.55,
  jitter: 0.65,
  quality: 0.5,
  label: 'stone'
});

return assembled;
